/** Offline completed-baseline review only: never authenticates or calls a host/database. */
import {readFile,writeFile} from 'node:fs/promises';
import {readM78ContinuationJournal,cleanM78ContinuationJournal,readM78Prior} from '../../tools/staging/check-m78-continuation';
import {assertM78ContinuationBaseline} from '../../tools/staging/m78-continuation-plan';
import {preservesM77History} from '../../tools/staging/check-m77-hosted';
import {decodeScope1Register} from '../../apps/site-web/src/lib/m78-api';
import {m78Continuation2SourcePins,M78_CONTINUATION2_EVIDENCE_PINS} from '../../tools/staging/m78-continuation2-source-pins';
import {readM78Continuation2Diagnostics} from '../../tools/staging/check-m78-continuation2';
import {m78CanonicalJson as canonical} from '../../packages/neuvetra-database/src/m78-validation';
const sha=(b:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(b).digest('hex'),check=(v:unknown,m:string)=>{if(!v)throw Error(m)},same=(a:unknown,b:unknown)=>canonical(a)===canonical(b);
export interface ClosedBaselineAdmission {journalSha256:string;journalHead:string;diagnosticsSha256:string;diagnosticsHead:string;gatePath:string;gateSha256:string;toolingCommit:string}
export async function verifyBaseline(text:string,diagnosticText:string,admission:ClosedBaselineAdmission){
 const expectedSha=admission.journalSha256,expectedHead=admission.journalHead;
 check(sha(text)===expectedSha,'Exact closed journal hash');const raw=JSON.parse(text.split('\n')[0]!),company=raw.workspaceId,events=readM78ContinuationJournal(text,company);cleanM78ContinuationJournal(events);
 const finish=events.at(-1)!;check(finish.kind==='attempt_finished'&&finish.mode==='baseline'&&finish.sha256===expectedHead&&finish.data.status==='passed'&&finish.data.applicationPostRequests===0&&finish.data.unknownAuthSessions===0&&finish.data.allCreatedAuthSessionsClosed===true,'Closed successful baseline required');
 check(events.every(e=>e.mode==='baseline'&&!e.kind.startsWith('post_'))&&events.filter(e=>e.kind==='baseline').length===1&&events.filter(e=>e.kind==='attempt_started').length===1,'Single zero-write baseline');
 const gatePath=admission.gatePath;check(/^\.superpowers\/m78-continuation2-[a-z0-9-]*gate\.json$/.test(gatePath),'Fixed continuation2 gate namespace');const gb=await readFile(gatePath);check(sha(gb)===admission.gateSha256,'Immutable gate');const gate=JSON.parse(gb.toString());check(same(events.find(e=>e.kind==='attempt_started')!.data.gate,gate.gate),'Journal gate');
 for(const pin of Object.values(gate.artifacts) as {path:string;sha256:string}[])check(sha(await readFile(pin.path))===pin.sha256,'Gate artifact '+pin.path);
 const pins=await m78Continuation2SourcePins(),receipt=JSON.parse(await readFile(gate.artifacts.independentReview.path,'utf8'));check(pins.length===160&&same(pins,gate.sourcePins)&&same(pins,receipt.sourcePins)&&same(receipt.evidencePins,M78_CONTINUATION2_EVIDENCE_PINS),'Exact full source/evidence closure');for(const pin of M78_CONTINUATION2_EVIDENCE_PINS)check(sha(await readFile(pin.path))===pin.sha256,'Original evidence');
 const runtime=JSON.parse(await readFile(gate.artifacts.runtime.path,'utf8')),ci=JSON.parse(await readFile(gate.artifacts.ciChecks.path,'utf8')),commit='59cda7a62d8dcc6b554c92372e3b032577e410c9';check(runtime.status==='m78_runtime_verified'&&runtime.schemaVersion===21&&runtime.commit===commit&&runtime.deploymentId==='0f2e99f3-67ef-4f4c-b3c3-a39c62eabc78'&&runtime.imageDigest==='sha256:fe46a0e354252026f2bcbf6672e10ec550e52a56f064ab3e75a8af17625749c9'&&runtime.httpStatus===200&&ci.sha===admission.toolingCommit&&ci.pr_head===admission.toolingCommit&&ci.checks.length===6&&ci.checks.every((c:any)=>c.conclusion==='success'),'Accepted runtime and CI');
 check(gate.profile==='m78-root-continuation2-journey-gate-v1'&&gate.mode==='baseline'&&receipt.status==='m78_independent_continuation2_preparation_passed'&&gate.gate.reviewedApplicationCommit===commit,'Correct outer gate and source receipt');
 const age=Date.parse(events.find(e=>e.kind==='attempt_started')!.createdAt)-Date.parse(runtime.observedAt);check(age>=0&&age<=15*60*1000,'Runtime fresh at admission');
 const diag=verifyDiagnostics(diagnosticText,admission.diagnosticsSha256,admission.diagnosticsHead,finish.data.requests);check(Date.parse(diag.startedAt)<=Date.parse(events[0]!.createdAt)&&Date.parse(diag.finishedAt)>=Date.parse(finish.createdAt),'Diagnostic phase brackets actual main journal');
 for(const role of ['manager1','manager2','member','outsider'])check(events.filter(e=>e.kind==='auth_outcome'&&e.data.role===role&&e.data.status===200&&e.data.tokenObserved===true&&e.data.subjectMatched===true).length===1&&events.filter(e=>e.kind==='logout_outcome'&&e.data.role===role&&e.data.status===204).length===1,'Exact main session closure');check(events.filter(e=>e.kind==='legacy_auth_outcome'&&e.data.action==='login'&&e.data.status===200).length===4&&events.filter(e=>e.kind==='legacy_auth_outcome'&&e.data.action==='logout'&&e.data.status===204).length===4,'Exact legacy session closure');
 const ready=events.find(e=>e.kind==='actual_readiness')!.data;check(ready.schemaVersion===21&&ready.applicationCommitAttestation===commit&&ready.sourceGate===gate.gate.independentReviewSha256&&ready.migrationSha256===gate.gate.migrationSha256,'Actual journal readiness');
 const baseline=events.find(e=>e.kind==='baseline')!.data,prior=await readM78Prior(company),decoded=await decodeScope1Register(baseline.scope1,company);assertM78ContinuationBaseline(decoded);check(same(decoded,baseline.scope1)&&same(decoded.inventory.versions[0],prior.observation.version.payload),'Retained exact committed version');let downloadCount=0;for(const old of [prior.previous,prior.failed]){preservesM77History(old.registers,baseline.registers);for(const family of Object.keys(old.downloads))for(const[key,value]of Object.entries(old.downloads[family])){check(same(value,baseline.downloads[family]?.[key]),'Old exact download');downloadCount++}}check(same(baseline.legacy,prior.old.legacy)&&same(baseline.legacy,prior.failed.legacy),'Exact legacy state');
 const v=decoded.inventory.versions[0]!,expected=canonical({...v,review:null}),entries:Record<string,{sha256:string;byteLength:number}>={['version_'+v.id]:{sha256:sha(expected),byteLength:Buffer.byteLength(expected)}};for(const s of v.statements)entries['statement_'+s.id]={sha256:sha(s.text),byteLength:Buffer.byteLength(s.text)};check(same(entries,baseline.m78bytes),'Exact retained version export/statement bytes');
 return {status:'m78_independent_continuation2_hosted_baseline_passed',createdAt:new Date().toISOString(),reviewerId:'/root/resume_release',journalPath:'.superpowers/m78-hosted-continuation2.jsonl',prefixSha256:expectedSha,headSha256:expectedHead,verifiedPrefixEvents:events.length,verifiedPrefixBytes:Buffer.byteLength(text),completedAt:finish.createdAt,requests:finish.data.requests,applicationPostRequests:0,allCreatedAuthSessionsClosed:true,unknownAuthSessions:0,mainLogins:events.filter(e=>e.kind==='auth_outcome').length,mainLogouts:events.filter(e=>e.kind==='logout_outcome').length,legacyAuthOutcomes:events.filter(e=>e.kind==='legacy_auth_outcome').length,sourcePinCount:160,applicationCommit:commit,schemaVersion:21,gatePath,gateSha256:sha(gb),oldHistoryAndDownloadsPreserved:true,priorDownloadComparisons:downloadCount,retainedInitialInventoryId:v.id,retainedInitialInventorySha256:v.versionSha256,m78ExactDownloadCount:Object.keys(entries).length,actualDecoderPassed:true,diagnosticSha256:admission.diagnosticsSha256,diagnosticHead:admission.diagnosticsHead,diagnosticEvents:diag.events,diagnosticRequests:diag.requests,diagnosticsVerifyBodies:false,toolingCommit:admission.toolingCommit,qaNetworkUsed:false,qaDatabaseUsed:false,hostedExerciseAccepted:false,fullLifecycleVerified:false};
}
export function verifyDiagnostics(text:string,expectedSha:string,expectedHead:string,expectedRequests:number){
 check(sha(text)===expectedSha,'Exact diagnostic hash');const es=readM78Continuation2Diagnostics(text),first=es[0]!,last=es.at(-1)!;check(first.kind==='phase_started'&&first.data.failedBaselineSha256==='8525a8416b3e55f07d508c9a9ec17fc8ac0a4902e798534dc05e9f4df72d1a46'&&first.data.failedBaselineHead==='e766f74b730bebf69849945407598c011f918b9a77b7ff9c3a5913cd6964f744'&&first.data.journal==='.superpowers/m78-hosted-continuation2.jsonl','Exact diagnostic parent');check(last.sha256===expectedHead&&last.kind==='phase_finished'&&last.data.status==='passed'&&last.data.diagnosticsHealthy===true&&last.data.applicationPostRequests===0&&last.data.allCreatedAuthSessionsClosed===true,'Diagnostic passed closure');
 const requests=new Map<number,any>();let ordinal=0,lastTime=0;for(const e of es){const timestamp=Date.parse(e.createdAt);check(Number.isFinite(timestamp)&&timestamp>=lastTime&&e.mode==='baseline','Diagnostic chronology/mode');lastTime=timestamp;if(e.kind==='request_intent'){check(e.data.ordinal===++ordinal&&['GET','POST'].includes(e.data.method),'Diagnostic request order');check(e.data.method!=='POST'||['auth:/auth/v1/token','auth:/auth/v1/logout'].includes(e.data.route),'No diagnostic application POST');requests.set(ordinal,{...e.data,outcome:null})}else if(e.kind==='response_headers'){const r=requests.get(e.data.ordinal);check(r&&r.outcome===null&&Number.isInteger(e.data.status)&&[200,204,401,403].includes(e.data.status)&&Number.isFinite(e.data.elapsedMs)&&e.data.elapsedMs>=0,'Paired successful/expected-denial headers');if(r.route==='auth:/auth/v1/token')check(e.data.status===200,'Login headers');if(r.route==='auth:/auth/v1/logout')check(e.data.status===204,'Logout headers');r.outcome=e.data}else check((e===first&&e.kind==='phase_started')||(e===last&&e.kind==='phase_finished'),'No errors or extra diagnostic phase')}
 check(requests.size===expectedRequests&&[...requests.values()].every(r=>r.outcome!==null),'Complete paired requests');check([...requests.values()].filter(r=>r.route==='auth:/auth/v1/token').length===8&&[...requests.values()].filter(r=>r.route==='auth:/auth/v1/logout').length===8,'All main and legacy diagnostic sessions');return {events:es.length,requests:requests.size,startedAt:first.createdAt,finishedAt:last.createdAt};
}
if(import.meta.main){check(process.argv.length===3,'Explicit closed admission file required');const admission=JSON.parse(await readFile(process.argv[2]!,'utf8'))as ClosedBaselineAdmission;const result=await verifyBaseline(await readFile('.superpowers/m78-hosted-continuation2.jsonl','utf8'),await readFile('.superpowers/m78-hosted-continuation2-diagnostics.jsonl','utf8'),admission);const out='evaluations/research-qa/m78-continuation2-baseline-independent-result.json';await writeFile(out,JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({path:out,sha256:sha(await readFile(out)),...result}))}

import {test,expect} from 'bun:test'
import {verifyDiagnostics,verifyBaseline} from './m78-continuation2-baseline-independent-review'
import {m78CanonicalJson as canonical} from '../../packages/neuvetra-database/src/m78-validation'
import {readFile} from 'node:fs/promises'
const sha=(v:string)=>new Bun.CryptoHasher('sha256').update(v).digest('hex')
const seed=()=>{const es:any[]=[{kind:'phase_started',data:{failedBaselineSha256:'8525a8416b3e55f07d508c9a9ec17fc8ac0a4902e798534dc05e9f4df72d1a46',failedBaselineHead:'e766f74b730bebf69849945407598c011f918b9a77b7ff9c3a5913cd6964f744',journal:'.superpowers/m78-hosted-continuation2.jsonl'}}];for(let i=1;i<=16;i++){es.push({kind:'request_intent',data:{ordinal:i,method:'POST',route:'auth:/auth/v1/'+(i<=8?'token':'logout')}});es.push({kind:'response_headers',data:{ordinal:i,status:i<=8?200:204,elapsedMs:1}})}es.push({kind:'phase_finished',data:{status:'passed',diagnosticsHealthy:true,applicationPostRequests:0,allCreatedAuthSessionsClosed:true}});return es}
const freeze=(es:any[])=>{let previous:string|null=null;const lines=es.map((e,i)=>{const body={sequence:i+1,previousSha256:previous,profile:'m78-continuation2-diagnostic-v1',mode:'baseline',...e,createdAt:new Date(100000+i).toISOString()},hash=sha(canonical(body));previous=hash;return JSON.stringify({...body,sha256:hash})});const text=lines.join('\n')+'\n';return {text,sha:sha(text),head:previous!}}
test('diagnostic success pairs every header with intent and exact parent/phase/auth closure',()=>{const f=freeze(seed());expect(verifyDiagnostics(f.text,f.sha,f.head,16).requests).toBe(16);expect(()=>verifyDiagnostics(f.text,'0'.repeat(64),f.head,16)).toThrow();expect(()=>verifyDiagnostics(f.text,f.sha,f.head,17)).toThrow()})
test('rehashing cannot admit missing headers, application write, wrong status, parent or extra phase',()=>{for(const mutate of [(e:any[])=>e.splice(2,1),(e:any[])=>e[1].data.route='application:/workspace/:id/scope1-inventory',(e:any[])=>e[2].data.status=503,(e:any[])=>e[0].data.failedBaselineSha256='0'.repeat(64),(e:any[])=>e.splice(1,0,{kind:'phase_started',data:{}}),(e:any[])=>e.at(-1).data.status='failed']){const es=seed();mutate(es);const f=freeze(es);expect(()=>verifyDiagnostics(f.text,f.sha,f.head,16)).toThrow()}})
test('preserved actual failed24 fixture is never admitted as a completed baseline',async()=>{const text=await readFile('tools/staging/m78-continuation2-failed-baseline.jsonl','utf8');await expect(verifyBaseline(text,'',{journalSha256:sha(text),journalHead:'e766f74b730bebf69849945407598c011f918b9a77b7ff9c3a5913cd6964f744'}as any)).rejects.toThrow()})
